query:
query RaceResultsProfile($date: String, $venueCode: String) {
      videoReplay(date: $date, venueCode: $venueCode) {
        hkRaceDate
        raceNo
        overseasRaceIndicator
        videoPresentOrNot
        isVideoReplayOn
        language
      }
      raceMeetingProfile(date: $date, venueCode: $venueCode) {
        totalNumberOfRace
        currentNumberOfRace
        races {
          id
          no
          status
          runners {
            horse {
              id
              name_en
              name_ch
            }
            color
            id
            no
            handicapWeight
            jockey {
              code
              name_en
              name_ch
            }
            trainer {
              code
              name_en
              name_ch
            }
            last6run
            internationalRating
            sire
            sexNm {
              chinese
              english
            }
            age
            barrierDrawNumber
            gearInfo
            margin
            marginNm {
              chinese
              english
            }
            lbwNm {
              chinese
              english
            }
            winOdds
            finalPosition
            deadHeat
            status
          }
          judgeSigns {
            value_en
          }
          raceName_en
          raceName_ch
          postTime
          country_en
          country_ch
          distance
          go_en
          go_ch
          raceTrack {
            description_en
            description_ch
          }
          raceCourse {
            description_en
            description_ch
            displayCode
          }
          raceClass_en
          raceClass_ch
          raceResults {
            status
            raceTime
            mgnInd
          }
        }
        date
        venueCode
        pmPools {
          leg {
            number
            races
          }
          status
          comingleStatus
          oddsType
          name_en
          name_ch
          lastUpdateTime
          dividends(officialOnly: true) {
            winComb
            type
            div
            seq
            status
            guarantee
            partial
            partialUnit
          }
        }
        status
      }
    }
